ALTER TABLE `step` ADD `promptOrigin` text;--> statement-breakpoint
UPDATE `step` SET `promptOrigin` = json_object('kind', 'ci-fix', 'trigger', 'pre-push', 'round', CAST(substr(`prompt`, instr(`prompt`, '(round ') + 7, instr(`prompt`, '/') - instr(`prompt`, '(round ') - 7) AS INTEGER), 'roundsMax', CAST(substr(`prompt`, instr(`prompt`, '/') + 1, instr(`prompt`, ').') - instr(`prompt`, '/') - 1) AS INTEGER)) WHERE `prompt` LIKE '[ci-fix] Local pre-push hook rejected the closing push (round %';--> statement-breakpoint
UPDATE `step` SET `promptOrigin` = json_object('kind', 'ci-fix', 'trigger', CASE WHEN instr(`prompt`, char(10) || '- local pre-push hook（failure）') > 0 THEN 'pre-push' ELSE 'ci-checks' END, 'round', CAST(substr(`prompt`, instr(`prompt`, '（第 ') + 3, instr(`prompt`, ' 轮）') - instr(`prompt`, '（第 ') - 3) AS INTEGER), 'roundsMax', 3) WHERE `prompt` LIKE '[ci-fix] CI 修复轮（第 %';--> statement-breakpoint
UPDATE `step` SET `promptOrigin` = json_object('kind', 'merge-conflict', 'round', CAST(substr(`prompt`, instr(`prompt`, '（第 ') + 3, instr(`prompt`, ' 轮）') - instr(`prompt`, '（第 ') - 3) AS INTEGER), 'roundsMax', 2) WHERE `prompt` LIKE '[merge-conflict] 解冲突轮（第 %';--> statement-breakpoint
UPDATE `step` SET `promptOrigin` = json_object('kind', 'rework') WHERE `prompt` LIKE 'Rework request on this same session:%';
